on conflict (id) do update set nome = excluded.nome, cidade = excluded.cidade, distancia_km = excluded.distancia_km, categoria = excluded.categoria, preco = excluded.preco, faixa = excluded.faixa, descricao = excluded.descricao, o_que_fazer = excluded.o_que_fazer, endereco = excluded.endereco, horario = excluded.horario, dica = excluded.dica, link = excluded.link, ativo = true;
update public.config set pool_atualizado_em = now() where id = 1;
